  let thermo_offset = particle_index * SCHROEDER_THERMO_STRIDE;
  let mechanics_offset = particle_index * SCHROEDER_MECHANICS_STRIDE;
  let assignment_offset = particle_index * SCHROEDER_ASSIGNMENT_STRIDE;

